select m.message_id, m.message_title, m.message_type, cast(m.message_content as char) as message_content, m.message_level, m.biz_source, m.biz_id, m.redirect_url, m.recipient_id, m.recipient_role_key, m.biz_status, m.biz_handled, m.biz_entry_name, m.status, m.create_by, m.create_time, m.update_by, m.update_time, m.remark, case when r.message_id is not null then true else false end as is_read, r.read_time from sys_message m left join sys_message_read r on r.message_id = m.message_id and r.user_id = #{userId}
m.status = '1'
/* admin用户不做权限过滤 */
and ( m.recipient_role_key is null or m.recipient_role_key = ''
or m.recipient_role_key in
#{rk}
)
AND m.message_title like concat('%', #{message.messageTitle}, '%')
AND m.message_type = #{message.messageType}
AND m.message_level = #{message.messageLevel}
AND m.biz_source = #{message.bizSource}
AND r.message_id is null AND (m.biz_handled is null or m.biz_handled = '0')
AND ( r.message_id is not null OR m.biz_handled = '1' )
AND date_format(m.create_time, '%Y-%m-%d') >= date_format(#{message.params.beginTime}, '%Y-%m-%d')
AND date_format(m.create_time, '%Y-%m-%d') <= date_format(#{message.params.endTime}, '%Y-%m-%d')
order by m.message_id desc

select count(*) from sys_message m
left join sys_message_read r
    on r.message_id = m.message_id and r.user_id = #{userId}

    m.status = '1'


            /* admin用户不做权限过滤 */


            and (
                m.recipient_role_key is null
                or m.recipient_role_key = ''

                    or m.recipient_role_key in

                        #{rk}


            )



        AND m.message_title like concat('%', #{message.messageTitle}, '%')


        AND m.message_type = #{message.messageType}


        AND m.message_level = #{message.messageLevel}


        AND m.biz_source = #{message.bizSource}



            AND r.message_id is null
            AND (m.biz_handled is null or m.biz_handled = '0')


            AND (
                r.message_id is not null
                OR m.biz_handled = '1'
            )



        AND date_format(m.create_time, '%Y-%m-%d') >= date_format(#{message.params.beginTime}, '%Y-%m-%d')


        AND date_format(m.create_time, '%Y-%m-%d') <= date_format(#{message.params.endTime}, '%Y-%m-%d')

select count(*) from sys_message m where m.status = '1' and (m.biz_handled is null or m.biz_handled = '0')
/* admin用户不做权限过滤 */
and ( m.recipient_role_key is null or m.recipient_role_key = ''
or m.recipient_role_key in
#{rk}
)
and not exists (select 1 from sys_message_read r where r.message_id = m.message_id and r.user_id = #{userId})

select m.message_id as messageId, m.message_title as messageTitle, m.message_type as messageType, m.message_level as messageLevel, m.biz_source as bizSource, m.biz_id as bizId, m.redirect_url as redirectUrl, m.message_content as messageContent, m.recipient_role_key as recipientRoleKey, m.biz_status as bizStatus, m.biz_handled as bizHandled, m.biz_entry_name as bizEntryName, m.create_by as createBy, m.create_time as createTime, case when r.message_id is not null then true else false end as isRead, r.read_time as readTime from sys_message m left join sys_message_read r on r.message_id = m.message_id and r.user_id = #{userId} where m.status = '1' and r.message_id is null and (m.biz_handled is null or m.biz_handled = '0')
/* admin用户不做权限过滤 */
and ( m.recipient_role_key is null or m.recipient_role_key = ''
or m.recipient_role_key in
#{rk}
)
order by m.message_id desc limit #{limit}

